139	package hotel.web;
140	
141	import com.fasterxml.jackson.databind.ObjectMapper;
142	import com.fasterxml.jackson.databind.SerializationFeature;
143	import com.fasterxml.jackson.databind.json.JsonMapper;
144	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
145	import hotel.messages.SentMessages;
146	import hotel.reports.OccupancyReport;
147	import hotel.reports.RevenueReport;
148	import hotel.reservations.ErrorCode;
149	import hotel.reservations.Guest;
150	import hotel.reservations.HotelException;
151	import hotel.reservations.NewReservation;
152	import hotel.reservations.ReservationService;
153	import hotel.rooms.Rooms;
154	import io.javalin.Javalin;
155	import io.javalin.http.Context;
156	import io.javalin.json.JavalinJackson;
157	import java.time.LocalDate;
158	import java.time.YearMonth;
159	import java.time.format.DateTimeParseException;
160	
161	/** The HTTP API the inn's website and front desk call. */
162	public final class HttpApi {
163	
164	    private final Javalin server;
165	    private final Rooms rooms;
166	    private final ReservationService reservations;
167	    private final SentMessages sentMessages;
168	    private final OccupancyReport occupancyReport;
169	    private final RevenueReport revenueReport;
170	
171	    public HttpApi(
172	            Rooms rooms,
173	            ReservationService reservations,
174	            SentMessages sentMessages,
175	            OccupancyReport occupancyReport,
176	            RevenueReport revenueReport) {
177	        this.rooms = rooms;
178	        this.reservations = reservations;
179	        this.sentMessages = sentMessages;
180	        this.occupancyReport = occupancyReport;
181	        this.revenueReport = revenueReport;
182	
183	        ObjectMapper jsonMapper = JsonMapper.builder()
184	                .addModule(new JavaTimeModule())
185	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
186	                .build();
187	        this.server = Javalin.create(config -> {
188	            config.showJavalinBanner = false;
189	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
190	        });
191	        registerRoutes();
192	        registerErrorHandling();
193	    }
194	
195	    public Javalin server() {
196	        return server;
197	    }
198	
199	    private void registerRoutes() {
200	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
201	
202	        server.post("/reservations", ctx -> {
203	            NewReservation request = readNewReservation(ctx);
204	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
205	        });
206	        server.get("/reservations/{id}", ctx ->
207	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
208	        server.post("/reservations/{id}/confirmation", ctx ->
209	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
210	        server.post("/reservations/{id}/cancellation", ctx ->
211	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
212	        server.post("/reservations/{id}/check-in", ctx ->
213	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
214	        server.post("/reservations/{id}/check-out", ctx ->
215	                ctx.json(reservations.checkOut(reservationId(ctx))));
216	        server.get("/reservations/{id}/document", ctx ->
217	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
218	
219	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
220	
221	        server.get("/reports/occupancy", ctx -> {
222	            LocalDate night = readDate(ctx);
223	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
224	        });
225	        server.get("/reports/revenue", ctx -> {
226	            YearMonth month = readMonth(ctx);
227	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
228	        });
229	    }
230	
231	    private void registerErrorHandling() {
232	        server.exception(HotelException.class, (exception, ctx) -> {
233	            ctx.status(httpStatus(exception.errorCode()));
234	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
235	        });
236	    }
237	
238	    private static int httpStatus(ErrorCode errorCode) {
239	        return switch (errorCode) {
240	            case INVALID_REQUEST -> 400;
241	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
242	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
243	            case CAPACITY_EXCEEDED -> 422;
244	        };
245	    }
246	
247	    private static NewReservation readNewReservation(Context ctx) {
248	        CreateReservationRequest body;
249	        try {
250	            body = ctx.bodyAsClass(CreateReservationRequest.class);
251	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
252	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
253	        }
254	        if (body == null
255	                || body.roomNumber() == null
256	                || isBlank(body.guestName())
257	                || isBlank(body.guestEmail())
258	                || isBlank(body.guestCpf())
259	                || body.checkIn() == null
260	                || body.checkOut() == null
261	                || body.guests() == null
262	                || body.ratePlan() == null) {
263	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
264	        }
265	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
266	        return new NewReservation(
267	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
268	    }
269	
270	    private static long reservationId(Context ctx) {
271	        String id = ctx.pathParam("id");
272	        try {
273	            return Long.parseLong(id);
274	        } catch (NumberFormatException notANumber) {
275	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
276	        }
277	    }
278	
279	    private static LocalDate readDate(Context ctx) {
280	        String date = requiredQueryParam(ctx, "date");
281	        try {
282	            return LocalDate.parse(date);
283	        } catch (DateTimeParseException badDate) {
284	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
285	        }
286	    }
287	
288	    private static YearMonth readMonth(Context ctx) {
289	        String month = requiredQueryParam(ctx, "month");
290	        try {
291	            return YearMonth.parse(month);
292	        } catch (DateTimeParseException badMonth) {
293	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
294	        }
295	    }
296	
297	    private static String requiredQueryParam(Context ctx, String name) {
298	        String value = ctx.queryParam(name);
299	        if (value == null) {
300	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
301	        }
302	        return value;
303	    }
304	
305	    private static boolean isBlank(String text) {
306	        return text == null || text.isBlank();
307	    }
308	}

